mapper.select:
SELECT ws.id, ws.warehouse_id, ws.sku_id, ws.physical_stock, ws.available_stock, ws.locked_stock,
       s.safety_stock
FROM warehouse_stock ws JOIN sku s ON s.id = ws.sku_id

    AND ws.warehouse_id = #{warehouseId}
    AND ws.sku_id = #{skuId}

ORDER BY ws.created_at DESC, ws.id DESC

mapper.update:
UPDATE warehouse_stock

SET available_stock = available_stock - #{quantity},
locked_stock = locked_stock + #{quantity}

WHERE warehouse_id = #{warehouseId}
AND sku_id = #{skuId}
AND available_stock >= #{quantity}

UPDATE warehouse_stock
SET available_stock = available_stock + #{quantity},
locked_stock = locked_stock - #{quantity}
WHERE warehouse_id = #{warehouseId}
AND sku_id = #{skuId}
AND locked_stock >= #{quantity}

UPDATE warehouse_stock
SET physical_stock = physical_stock - #{quantity},
locked_stock = locked_stock - #{quantity}
WHERE warehouse_id = #{warehouseId}
AND sku_id = #{skuId}
AND physical_stock >= #{quantity}
AND locked_stock >= #{quantity}

UPDATE warehouse_stock
SET physical_stock = physical_stock + #{delta},
    available_stock = available_stock + #{delta}
WHERE warehouse_id = #{warehouseId} AND sku_id = #{skuId}
  AND physical_stock = #{physical} AND available_stock = #{available}
  AND locked_stock = #{locked} AND available_stock + #{delta} >= 0
